## 📦 三、智能合约设计（Solidity 示例）

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract C2Contract {
    struct Command {
        uint256 id;
        address sender;
        string payload;
        uint256 timestamp;
        bool executed;
    }

    mapping(uint256 => Command) public commands;
    uint256 public commandCount;

    event CommandStored(uint256 indexed id, address sender, string payload, uint256 timestamp);
    event CommandExecuted(uint256 indexed id);

    // 存储C2指令
    function storeCommand(string memory _payload) public {
        uint256 id = commandCount++;
        commands[id] = Command({
            id: id,
            sender: msg.sender,
            payload: _payload,
            timestamp: block.timestamp,
            executed: false
        });

        emit CommandStored(id, msg.sender, _payload, block.timestamp);
    }

    // 执行指令（设备端调用）
    function executeCommand(uint256 _id) public {
        require(commands[_id].executed == false, "Command already executed.");
        require(commands[_id].timestamp + 300 >= block.timestamp, "Command expired.");

        commands[_id].executed = true;
        emit CommandExecuted(_id);

        // 这里可以调用外部执行器，比如通过预言机（Oracle）或链下服务
        // 示例：通过预言机调用链下执行器
        // ChainlinkOracle.executeCommand(_id, commands[_id].payload);
    }

    // 获取指令详情
    function getCommand(uint256 _id) public view returns (Command memory) {
        return commands[_id];
    }
}
